import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO quote — item base premiums", () => {
  it.todo("empty item list → premium 5 G (only processing fee)");
  it.todo("single sword → base 100 + 5 fee = 105 G (newcomer with follow-up? treat per spec) ");
  it.todo("single amulet base 60");
  it.todo("single staff base 80");
  it.todo("single potion base 40");
});

describe("MHPCO quote — components and blocks", () => {
  it.todo("2 runes → 50 G base premium");
  it.todo("3 runes → 60 G base premium (block applies)");
  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
  it.todo("7 runes → 175 G base premium");
  it.todo("2 runes + 1 moonstone → 75 G base (no block: different types)");
  it.todo("3 runes + 3 moonstones → 120 G base (two separate blocks)");
});

describe("MHPCO quote — item modifiers", () => {
  it.todo("cursed sword only (newcomer) → 165 G (100 base + 50 curse + 10 first + 5 fee)");
  it.todo("sword enchantment 5 → high-enchantment surcharge applies (+30%)");
  it.todo("sword enchantment 4 → no high-enchantment surcharge");
  it.todo("cursed sword enchantment 5 → both surcharges apply");
});

describe("MHPCO quote — policy modifiers and scope", () => {
  it.todo("cursed sword + plain amulet → base 160, curse +50 (50% of sword base) → 210 before further modifiers/fee");
  it.todo("customer exactly 2 years → loyalty 20% discount applies");
  it.todo("first insurance surcharge is 10% per item base, applied per item regardless of customer history");
  it.todo("second contract in scenario gets 15% follow-up discount on policy base");
});

describe("MHPCO quote — rounding", () => {
  it.todo("premium 197.5 G → final premium 198 G (rounded up in office favor)");
});

describe("MHPCO quote — integration examples", () => {
  it.todo("newcomer cursed sword (steel, ench 3), 0 years → premium 165 G");
  it.todo("long-standing (3yr) 2nd contract, cursed sword (steel, ench 7) → premium 160 G");
});

describe("MHPCO quote — errors", () => {
  it.todo("quote with unknown item type (broomstick) → CLI non-zero exit, error to stderr, no results on stdout");
});

describe("MHPCO claim — standard reimbursement", () => {
  it.todo("regular sword (steel, ench 3), damage 500 → payout 400 (500 - 100 deductible)");
  it.todo("rune (value 250), damage 200 → payout 100 (200 - 100 deductible, no special clause)");
});

describe("MHPCO claim — special clauses", () => {
  it.todo("dragon-material sword ench 8, damage 1000 → payout 400 (50% then deductible)");
  it.todo("dragon-material sword ench 9, damage 1000 → payout 400 (both clauses, 50% wins, then deductible)");
  it.todo("dragon-material sword ench 5, damage 800 → payout 700 (dragon full, then deductible)");
  it.todo("steel sword ench 9, damage 1000 → payout 400 (high-ench 50% then deductible)");
});

describe("MHPCO claim — deductible per damage event", () => {
  it.todo("dragon attack: sword 500 + amulet 300 → payout 600 (deductible once per damaged item)");
});

describe("MHPCO claim — cap", () => {
  it.todo("cap = twice the insurance sum: sword+amulet → sum 1600, cap 3200");
  it.todo("cursed sword: cap 2000 based on unmodified insurance value; premium modifiers do not raise cap");
  it.todo("sword + 3 runes (block) → insurance sum 1750; block discount affects premium only, not sum");
  it.todo("two swords → insurance sum 2000, cap 4000");
  it.todo("cap exhaustion: sword sum 1000 cap 2000; claim 1500 → payout 1400 remainingCap 600; claim 1500 → payout 600 remainingCap 0");
});

describe("MHPCO claim — multiple items of same type", () => {
  it.todo("two swords, dragon attack damages both → each damage its own deductible");
  it.todo("more damages of a type than policy covers (2 sword damages, 1 sword insured) → CLI non-zero exit, claim rejected");
});

describe("MHPCO claim — rounding", () => {
  it.todo("payout 350.5 G → final payout 350 G (rounded down in office favor)");
});

describe("MHPCO claim — errors", () => {
  it.todo("claim references damage whose item not in policy (amulet damaged, only sword insured) → CLI non-zero exit, stderr error");
  it.todo("claim damage with unknown item type → CLI non-zero exit, stderr error");
  it.todo("claim damage amount -200 → CLI non-zero exit, stderr error");
});

describe("MHPCO CLI — end to end", () => {
  it.todo("schema example: amulet quote then claim → results array of correct shape");
});

