function itemOwnBase(item: Item): number {
  if (isComponent(item.type)) {
    return COMPONENT_BASE_PREMIUM;
  }
  return ITEM_BASE_PREMIUM[item.type];
}

function itemSurcharge(item: Item): number {
  const own = itemOwnBase(item);
