function processClaim(policy: Policy, incident: Incident): ClaimResult {
  let payout = 0;
  for (const damage of incident.damages) {
    const item = policy.items.find((i) => i.type === damage.itemType);
    if (item === undefined) {
      throw new Error(`Damaged item not in policy: ${damage.itemType}`);
    }
    payout += damagePayout(damage, item);
  }
  const granted = Math.min(payout, policy.remainingCap);
  policy.remainingCap -= granted;
  return { payout: granted, remainingCap: policy.remainingCap };
}

